<template><el-card><div class="flex gap-4 mb-4"><el-select v-model="filterDept" placeholder="Dept" clearable class="w-40"><el-option v-for="d in depts" :key="d.department_id" :label="d.department_name" :value="d.department_id" /></el-select><el-button type="primary" @click="search">Search</el-button></div><el-table :data="results" stripe><el-table-column label="Match" width="100"><template #default="{row}"><el-tag :type="(row.match_pct||0)>80?'success':(row.match_pct||0)>50?'warning':'info'">{{ row.match_pct||0 }}%</el-tag></template></el-table-column><el-table-column prop="full_name" label="Name" /><el-table-column prop="position_name" label="Position" /><el-table-column prop="department_name" label="Dept" /><el-table-column label="Action"><template #default="{row}"><el-button size="small" @click="$router.push('/profile')">View</el-button></template></el-table-column></el-table></el-card></template><script setup lang="ts">import {ref,onMounted}from 'vue';import {getEmployees,getDepartments,getMatch}from '@/api/hrms';const emit=defineEmits(['update-title']);emit('update-title','Talent Discovery');const depts=ref<any[]>([]);const results=ref<any[]>([]);const filterDept=ref('');async function search(){try{const r:any=await getEmployees({page:1,page_size:50});const emps=r.data?.list||[];const enriched:any[]=[];for(const e of emps){if(filterDept.value&&e.department_id!=filterDept.value)continue;try{const m:any=await getMatch(e.employee_id);enriched.push({...e,match_pct:m.data?.[0]?.match_pct})}catch{}}enriched.sort((a,b)=>(b.match_pct||0)-(a.match_pct||0));results.value=enriched.slice(0,30)}catch(e){}}onMounted(async()=>{try{const r:any=await getDepartments();depts.value=r.data||[]}catch{};search()})</script>
